(* [comment removed for export] *)
Lemma call_srd (fx : FPState) R M model s sm cr (X : Z) (tl : list Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 32) -> kept_rs R ->
  getr R (reg 10) = Z_to_bv 64 (fb + 64) -> getr R (reg 11) = Z_to_bv 64 (fb + 376) -> getr R (reg 12) = Z_to_bv 64 len ->
  st_ok M model s sm cr -> PM.unread (PM.p_src s) sm < 2 ^ 26 -> PM.vs_size (PM.p_tb s) + PM.unread (PM.p_src s) sm < 2 ^ 26 ->
  Z.of_nat (length tl) = PM.vs_size (PM.p_tb s) -> L5.bytes_at RSEGS M (PM.vs_data (fb + 376) (PM.p_tb s)) tl ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (s' : PM.pst) (sm' : PM.strm) (cr' : credit) (d : Z),
     regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 d -> 0 <= d <= len ->
     PMSP.consumed (PM.p_src s) (PM.p_src s') sm sm' = d -> PM.vs_size (PM.p_tb s') = PM.vs_size (PM.p_tb s) + d ->
     d = Z.min len (PM.unread (PM.p_src s) sm) ->
     L5.bytes_at RSEGS M' (PM.vs_data (fb + 376) (PM.p_tb s')) (tl ++ UbjRef.slice pl (PEC.pos_of pl (PM.p_src s) sm) d) ->
     PM.p_more s' = PM.p_more s -> PM.p_done s' = PM.p_done s -> PM.p_depth s' = PM.p_depth s ->
     PM.p_b s' = PM.p_b s -> PM.p_k s' = PM.p_k s -> PM.p_stk s' = PM.p_stk s ->
     PMSP.src_step (PM.p_src s) (PM.p_src s') sm sm' ->
     st_ok M' model' s' sm' cr' ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x3bcf4 M model) K.
